kh.buildDiagnosticReport=function(items,context){var href=String(window.location.href||'');var report={version:'v1',generatedAt:new Date().toISOString(),page:{href:href,origin:window.location.origin||'',pathname:window.location.pathname||'',search:window.location.search||'',hash:window.location.hash||'',readyState:document.readyState},catalog:{total:0,enabled:0,disabled:0,pageMatched:0,pageRunnable:0},summary:{available:0,waiting:0,unavailable:0,unsupported:0,warnings:0},errors:kh._lastCatalogError?[String(kh._lastCatalogError)]:[],actions:[]};(Array.isArray(items)?items:[]).forEach(function(item,index){var action=kh.normalizeAction(item,index+1);report.catalog.total+=1;if(action&&action.enabled)report.catalog.enabled+=1;else report.catalog.disabled+=1;if(!action)return;var diagnosed=kh.diagnoseAction(action,{href:href,scanValue:context&&context.scanValue||''});report.actions.push(diagnosed);if(diagnosed.participatesInCurrentPage)report.catalog.pageMatched+=1;if(diagnosed.participatesInCurrentPage&&diagnosed.status==='available')report.catalog.pageRunnable+=1;if(diagnosed.participatesInCurrentPage){report.summary[diagnosed.status]=(report.summary[diagnosed.status]||0)+1;report.summary.warnings+=Array.isArray(diagnosed.warnings)?diagnosed.warnings.length:0;}});return report;};
