kh.runSettingsDiagnostics=function(force,options){return kh.fetchActionCatalog(!!force).then(function(items){var report=kh.buildDiagnosticReport(items||[],options||{});kh._lastSettingsDiagnosticReport=report;kh.renderSettingsDiagnostics(report);kh.setSettingsStatus('动作核对已完成：当前页 '+String(report.catalog.pageMatched||0)+' 条，直接可执行 '+String(report.catalog.pageRunnable||0)+' 条','info');return report;}).catch(function(err){kh.setSettingsStatus('动作核对失败: '+String(err&&err.message||err||'unknown'),'err');throw err;});};
